window.FULL_DOCUMENT_1 = {"id":"doc-1","title":"Инструкция по работе котельного оборудования","source":"___________________________._1.docx","blocks":[{"type":"text","text":"Инструкция"},{"type":"text","text":"по работе"},{"type":"text","text":"котельного"},{"type":"text","text":"оборудования"},{"type":"text","text":"ОГЛАВЛЕНИЕ"},{"type":"text","text":"Водоподготовкастр. 3"},{"type":"text","text":"Снабжение котельной водойстр. 3"},{"type":"text","text":"Подача воды на химводоочистку (ХВО)стр. 8"},{"type":"text","text":"Химводоочистка (ХВО)стр. 9"},{"type":"text","text":"Подача воды в деаэраторстр. 12"},{"type":"text","text":"Деаэраторстр. 18"},{"type":"text","text":"ГРУстр. 20"},{"type":"text","text":"Система автоматического отключения подачи газастр. 22"},{"type":"text","text":"Последовательность действий для взведения клапановстр. 24"},{"type":"text","text":"Котлыстр. 24"},{"type":"text","text":"Устройство котластр. 24"},{"type":"text","text":"Чистка индикатора уровня воды на котлах при помощи продувкистр. 24"},{"type":"text","text":"Запуск котластр. 27"},{"type":"text","text":"Запуск котла без давлениястр. 33"},{"type":"text","text":"Кратковременная остановка котла с активированным устройством пуска, готовности и снижения нагрузкистр. 35"},{"type":"text","text":"Включение котла после кратковременной остановки с активированным устройством пуска, готовности и снижения нагрузкистр. 36"},{"type":"text","text":"Выключение котла с активированным устройством пуска, готовности и снижения нагрузкистр. 37"},{"type":"text","text":"Останов и запуск котла после авариистр. 38"},{"type":"text","text":"Магистраль парастр. 38"},{"type":"text","text":"Система отоплениястр. 39"},{"type":"text","text":"Система горячего водоснабжениястр. 41"},{"type":"text","text":"Управление настенным газовым котломстр. 42"},{"type":"text","text":"Конденсатстр. 44"},{"type":"text","text":"Обязанности диспетчерастр. 44"},{"type":"text","text":"1. Водоподготовка."},{"type":"text","text":"1.1 Снабжение котельной водой."},{"type":"text","text":"Снабжение котельной водой происходит от двух источников (Скважина №2 и вода с ТЭЦ)."},{"type":"text","text":"1.1.1 Скважина №2."},{"type":"text","text":"Скважина находится в конце завода между градирней и бункером пескоприемника. Производительность скважины 12 метров кубических в час. Производительность насоса, установленного в скважине, 10 метров кубических в час. Управление насосом происходит через частотный преобразователь рис. № 2, установленный в пескоприемнике. Обороты двигателя регулируются частотным преобразователем в зависимости от давления в магистрали водопровода, измеряемое датчиком давления, который установлен у большого смесителя (рис. № 1). Тут же установлен манометр. Давление в магистрали должно быть около 9 бар."},{"type":"image","src":"images/doc1_000.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 1"},{"type":"text","text":"Запуск насоса происходит с частотного преобразователя (рис № 2). При включенном питании автомат № Q1 на дисплее светится надпись rdY – готовность к запуску. Затем включаем автомат № Q2, происходит запуск насоса на дисплее во время нормальной работы насоса должно показываться число от 30 до 50 – это частота в герцах."},{"type":"text","text":"Если произошла аварийная остановка насоса, то на дисплее высвечиваются ошибки, записываем номер ошибки, после чего сбрасываем ее. Чтобы скинуть ошибку нужно произвести следующие действия:"},{"type":"text","text":"-выключить автомат № Q2,"},{"type":"text","text":"-выключить автомат № Q1,"},{"type":"text","text":"- подождать, когда погаснет дисплей,"},{"type":"text","text":"- включить автомат № Q1 на дисплее должна появиться надпись rdY,"},{"type":"text","text":"- включить автомат № Q2 на дисплее должно появиться - число частоты оборотов двигателя насоса в герцах."},{"type":"text","text":"В случае если насос не запускается и появляется та же ошибка, делается звонок зам. энергетика, сообщается код ошибки, ждем указаний по дальнейшим действиям."},{"type":"image","src":"images/doc1_001.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 2"},{"type":"text","text":"Далее вода подается по трубопроводу из белого полипропилена, вдоль стены через весь завод в помещение скважины № 1. В помещении компрессорной от магистрали есть ответвление, через которое происходит снабжение АБК холодной водой. Вода подается через сетчатый фильтр грубой очистки, редуцирующий клапан, в котором происходит понижение давления с 8 бар до 3 бар и далее через фильтр тонкой очистки см. рис 3."},{"type":"text","text":"Рис. № 3"},{"type":"image","src":"images/doc1_002.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"В помещении скважины вода подается в магистраль и далее через грязевик отстойник в котельную. На грязевике установлен манометр, по которому контролируется наличие давления в магистрали и соответственно работа насоса (рис. № 4)."},{"type":"image","src":"images/doc1_003.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 4"},{"type":"text","text":"1.1.2 Вода с ТЭЦ."},{"type":"text","text":"Вода с ТЭЦ подается по подземному трубопроводу, который входит в помещение скважины. От этого трубопровода запитана пожарная магистраль вентиль № 1, и также может происходить водоснабжение котельной."},{"type":"text","text":"1.1.3 Переключение водоснабжения котельной от скважины № 2 на воду с ТЭЦ и на оборот."},{"type":"text","text":"Основное водоснабжение котельной происходит от скважины, водоснабжение от ТЭЦ может быть временным при аварийных ситуациях и ремонтных работах магистрали и скважины."},{"type":"text","text":"Переключение водоснабжения от скважины на воду от ТЭЦ:"},{"type":"text","text":"- Закрываем вентиль № 2 и № 4 - подача воды на горячее водоснабжение АБК, эти краны должны быть обязательно закрыты, чтобы не допустить попадания воды с ТЭЦ на АБК не по холодной и не по горячей магистралям."},{"type":"text","text":"- открываем затвор № 3, плавно повышая давление"},{"type":"text","text":"- далее идет переключение снабжения горячей, холодной водой АБК со скважины №1."},{"type":"text","text":"Переключение снабжения горячей, холодной водой АБК со скважины №1:"},{"type":"text","text":"-перекрываем шаровые краны подачи воды на АБК в компрессорной, рис. № 3"},{"type":"text","text":"-закрываем кран слива воды со скважины №1, он находится внизу под шаровым краном №5 подачи воды со скважины №1 рис.№5"},{"type":"text","text":"-открываем шаровые краны №5 и №6 подачи воды со скважины №1 на АБК"},{"type":"text","text":"-включаем автомат №5, запускаем частотный преобразователь управления скважиной №1 рис.№6"},{"type":"image","src":"images/doc1_004.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 5"},{"type":"image","src":"images/doc1_005.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 6"},{"type":"text","text":"Переключение воды с ТЭЦ на воду от скважины:"},{"type":"text","text":"- Закрываем затвор № 3"},{"type":"text","text":"- открываем кран № 2"},{"type":"text","text":"- после выключения скважины №1закрываем краны №5, №6 рис. №5"},{"type":"text","text":"-открываем кран № 4"},{"type":"text","text":"-открываем шаровые краны подачи воды на АБК в компрессорной, рис. № 3"},{"type":"text","text":"1.2 Подача воды на химводоочистку (ХВО)."},{"type":"text","text":"Из помещения скважины № 1 вода подается в котельную (рис.7). На входе воды в котельную стоит затвор, который перекрывает подачу воды на ХВО, после затвора стоит редуцирующий клапан задача которого понижение давления воды до 6 бар. Т.к. все оборудование котельной по водоподготовке рассчитано на максимальное давление 6 бар. После редуцирующего клапана идет отвод воды на технологию и барботёр (один из вариантов), далее стоит манометр, по которому контролируем давление после редуцирующего клапана, и предохранительный клапан на 6 бар, который стравливает избыточное давление в канализацию. Затем стоит система очистки воды, состоящая из фильтра грубой очистки (сетчатый фильтр) и двух параллельных фильтров тонкой очистки. После системы очистки также стоит манометр перед входом воды в систему ХВО, по которому мы определяем падение давления на системе очистки, относительно показаний манометра перед системой фильтров.  Разность давлений не должна превышать 1.0 бар."},{"type":"text","text":"Если падение давления больше 1,0 бар тогда нужно произвести обслуживание системы очистки воды."},{"type":"image","src":"images/doc1_006.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 7"},{"type":"text","text":"1.2.1 Обслуживание системы очистки воды."},{"type":"text","text":"Если падение давления превышает 1,0 бар, то нужно произвести следующие действия."},{"type":"text","text":"- Почистить фильтр грубой очистки. Закрыть затвор, выкрутить фильтр, промыть сетку, закрутить обратно. Открыть затвор (открытие затвора произвести плавно во избежание гидроудара). Сравнить падение давления на манометрах. В большинстве случаев хватает чистки сетчатого фильтра. Если падение давления осталось также больше 1,0 бар тогда меняем фильтра тонкой очистки."},{"type":"text","text":"- Замена фильтра тонкой очистки. Перекрываем краны с обоих концов фильтра тонкой очистки на одной линии. Отверткой откручиваем сбросной клапан, который служит для сбрасывания излишнего давления и выпуска воздуха из фильтра. Клапан находится сверху фильтра. Если не сбросить излишки давления, то фильтр не открутить. Затем раскручиваем фильтр, вынимаем старый картридж, промываем стакан, ставим новый картридж, закручиваем стакан. Приоткрываем кран, который впускает воду в фильтр (приоткрываем немного) и следим, когда выйдет весь воздух из фильтра через сбросной клапан. После того как вышел весь воздух закручиваем сбросной клапан, и открываем входной и выходной краны. Затем проводим точно такую же процедуру по замене фильтра тонкой очистки на второй линии."},{"type":"text","text":"1.3 Химводоочистка (ХВО)."},{"type":"text","text":"НАЗНАЧЕНИЕ. Умягчение воды, используемой для хозяйственно-питьевых нужд, в системах отопления и горячего водоснабжения, для подпитки котельных установок, в технологических линиях пищевых производств."},{"type":"text","text":"ПРИНЦИП ДЕЙСТВИЯ. Умягчение воды на установках осуществляется методом натрий-катионирования при фильтровании исходной воды через слой ионообменной смолы с обменной емкостью не менее 1,2 г-экв/л. Регенерация ионообменной смолы производится раствором поваренной соли автоматически с заданной периодичностью."},{"type":"text","text":"ТЕХНИЧЕСКИЕ ХАРАКТЕРИСТИКИ"},{"type":"text","text":"1. Установка умягчения воды состоит из трех основных элементов – двух натрий-катионитных фильтров с расположенным наверху одного из них блоком управления, и бака-солерастворителя."},{"type":"text","text":"2. Установки умягчения воды выпускаются с блоками автоматического управления процессом регенерации по сигналу встроенного счетчика, регистрирующего объем воды, прошедшей через установку. Возможен вывод установки на регенерацию по сигналу от встроенного таймера."},{"type":"text","text":"3. Блок управления состоит из многоходового клапана, переключающего потоки воды во время регенерации установки, и программного устройства, используемого для настройки параметров процесса регенерации. Блок управления осуществляет попеременную регенерацию каждого из двух натрий-катионитных фильтров."},{"type":"text","text":"ОПИСАНИЕ И ПРИНЦИП РАБОТЫ"},{"type":"text","text":"1. В состав установки умягчения воды входят следующие элементы:"},{"type":"text","text":"- два натрий-катионитных фильтра;"},{"type":"text","text":"- электромеханический блок автоматического управления процессом регенерации фильтров;"},{"type":"text","text":"- бак-солерастворитель."},{"type":"text","text":"2. Натрий-катионитный фильтр состоит из:"},{"type":"text","text":"- корпуса;"},{"type":"text","text":"- ионообменной смолы;"},{"type":"text","text":"- поддерживающей засыпки"},{"type":"text","text":"- дренажно-распределительной системы."},{"type":"text","text":"3. Корпус каждого фильтра изготовлен из полиэтилена высокой плотности с наружным покрытием из стекловолокна на эпоксидной смоле."},{"type":"text","text":"В корпусе имеется верхнее резьбовое отверстие для установки дренажно-распределительной системы, загрузки фильтрующих материалов, крепления блока управления."},{"type":"text","text":"4. Дренажно-распределительная система фильтра включает в себя:"},{"type":"text","text":"- верхний щелевой экран в виде щелевого колпачка;"},{"type":"text","text":"- вертикальный коллектор (центральный стояк);"},{"type":"image","src":"images/doc1_007.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"5. Верхний экран служит для предотвращения выноса в канализацию ионообменной смолы при ее обратной промывке."},{"type":"text","text":"6. В состав блока управления входят:"},{"type":"text","text":"- программное устройство, используемое для установки частоты, времени начала и продолжительности процесса регенерации фильтра;"},{"type":"text","text":"- многоходовой клапан, переключение которого во время регенерации фильтра полностью заменяет стандартную запорно-регулирующую арматуру;"},{"type":"text","text":"- встроенные эжектор для отбора раствора соли из бака-солерастворителя и защитный экран эжектора;"},{"type":"text","text":"- электродвигатель многоходового клапана;"},{"type":"text","text":"- адаптер и соединительные трубы для присоединения многоходового клапана ко второму фильтру;"},{"type":"text","text":"- один крыльчатый счетчик воды специальной конструкции, монтируемый на многоходовом клапане."},{"type":"text","text":"7. В состав бака-солерастворителя входят следующие элементы:"},{"type":"text","text":"- корпус и крышка из полиэтилена высокой плотности;"},{"type":"text","text":"- солевая решетка;"},{"type":"text","text":"- солезаборник со встроенным воздушным клапаном;"},{"type":"text","text":"- защитный кожух солезаборника с крышкой;"},{"type":"text","text":"- переливной штуцер;"},{"type":"text","text":"- угловая муфта и гибкий шланг для присоединения солезаборника к блоку управления."},{"type":"text","text":"8. Принцип действия установки умягчения воды основан на методе натрий-"},{"type":"text","text":"катионирования."},{"type":"text","text":"В результате ионного обмена из воды удаляются катионы Ca2+ и Mg2+, а вода обогащается ионами Na+ в соответствии с реакциями:"},{"type":"text","text":"Ca2+ + RNa == 2Na+ + RCa"},{"type":"text","text":"Mg2++ RNa == 2Na+ + RMg"},{"type":"text","text":"Восстановление регенерирующей способности смолы осуществляется посредством пропуска раствора"},{"type":"text","text":"поваренной соли NaCl. При этом протекают обратные реакции:"},{"type":"text","text":"2Na+ + RCa == Ca2++ RNa"},{"type":"text","text":"2Na+ + RMg == Mg2++ RNa"},{"type":"text","text":"Удаленные в ходе регенерации катионы жесткости отводятся в канализацию."},{"type":"text","text":"9. Режим работы установки:"},{"type":"text","text":"- один катионитный фильтр всегда находится в рабочем режиме, второй в режиме регенерации или ожидания;"},{"type":"text","text":"- одновременное переключение обоих фильтров из одного режима в другой происходит после того, как встроенный счетчик зафиксирует окончание пропуска заданного объема воды (что соответствует нулевому значению на табло блока управления) либо после истечения заданного периода времени;"},{"type":"text","text":"- после переключения фильтров показания счетчика возвращаются в исходное положение, соответствующее заданному значению фильтроцикла;"},{"type":"text","text":"- сразу после переключения начинается регенерация фильтра, находившегося до этого в рабочем режиме, и по окончании регенерации он переходит в режим ожидания."},{"type":"text","text":"10. Регенерация осуществляется путем обработки ионообменной смолы раствором поваренной соли из бака-солерастворителя."},{"type":"text","text":"Все операции процесса регенерации выполняются автоматически за счет давления исходной воды без использования промежуточных емкостей и насосов."},{"type":"text","text":"Концентрированный раствор соли в баке-солерастворителе образуется в результате ее контакта с соответствующим объемом воды. Для получения концентрированного солевого раствора необходим контакт избыточного количества соли с водой, для чего в солевом баке всегда должен находиться запас соли не менее чем на 2 – 3 регенерации. Показателем насыщенности солевого раствора является наличие нерастворенной соли в баке при продолжительном контакте соли с водой (в течение не менее 4-5ч)."},{"type":"text","text":"Периодическая загрузка соли в бак осуществляется обслуживающим персоналом."},{"type":"text","text":"Во всех операциях процесса регенерации одного фильтра используется умягченная вода, вырабатываемая другим фильтром, находящимся в рабочем режиме."},{"type":"text","text":"11. Сброс сточных вод, образующихся в процессе регенерации, производится в хозяйственно-бытовую или производственную канализацию."},{"type":"text","text":"12. Процесс регенерации каждого катионитного фильтра в составе установок состоит из следующих операций:"},{"type":"text","text":"• Операция 1 – обратная промывка смолы умягченной водой, подаваемой в направлении снизу вверх. Служит для взрыхления и очистки смолы от накопившегося осадка."},{"type":"text","text":"• Операция 2 – обработка смолы раствором соли и медленная отмывка."},{"type":"text","text":"Концентрированный раствор (26%) из бака-солерастворителя через солезаборник по гибкому шлангу поступает в блок управления, где смешивается с умягченной водой до рабочей концентрации (7-10%), и затем подается в катионитный фильтр в направлении сверху вниз (по прямоточной схеме). Отбор раствора из бака происходит за счет вакуума, образующегося во встроенном эжекторе под давлением воды."},{"type":"text","text":"После опорожнения солевого бака эжектирующая вода продолжает поступать в регенерируемый фильтр, то есть производится медленная прямоточная отмывка слоя смолы. При этом встроенный в солезаборник воздушный клапан предотвращает подсос воздуха из солевого бака в солевую линию."},{"type":"text","text":"• Операция 3 – быстрая прямоточная отмывка смолы умягченной водой для уплотнения ее слоя и удаления из него остатков отработанного регенерационного раствора соли."},{"type":"text","text":"• Операция 4 – заполнение водой бака-солерастворителя."},{"type":"text","text":"Заданный объем умягченной воды заливается в бак-солерастворитель. Этот объем определяет дозу соли на регенерацию установки."},{"type":"text","text":"После системы очистки вода проходит через ХВО. В нашей котельной установлены три ступени, в работе используются только две. Каждая ступень состоит из двух фильтров (см. устройство ХВО выше). Сначала вода проходит через первую ступень, где происходит основное умягчение воды с понижением жёсткости 3000 до 200. Затем вода проходит через вторую ступень, где происходит доумягчение с понижением жёсткости с 200 до 20 – 35. После каждой ступени врезан манометр, показывающий падение давления на ступени. Падение должно быть примерно 1-1,5 бар на каждой ступени. Падение давления зависит от того находится ли ступень на промывке (регенерации) или нет.  Давление после обеих ступеней при нормальном водоотборе и отсутствии промывок на ступенях должно быть минимум 2-2,5 бар. Во время заборов анализов лаборантками, помощник диспетчера должен находится в котельной, проконтролировать правильность заборов анализов и снять показания со ступеней ХВО с занесением в таблицу."},{"type":"text","text":"1.4 Подача воды в деаэратор."},{"type":"text","text":"Вода с ХВО подается через теплообменники, где происходит ее нагревание в накопительный бак ХВО, находящийся на улице. С бака ХВО вода подается насосом через систему клапанов в деаэратор."},{"type":"text","text":"1.4.1 Подача воды через теплообменники (см. схему водоподготовки котельной)."},{"type":"image","src":"images/doc1_008.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Схема водоподготовки котельной."},{"type":"text","text":"Умягченная вода (температура которой 5-7 градусов) подается под своим давлением через теплообменники в накопительный бак ХВО. В теплообменниках происходит подогрев воды до 30-90 градусов. Подогрев происходит горячим конденсатом. Конденсат циркулирует через теплообменники. Подается конденсат при помощи насоса №3 (рис.9) с бака конденсата, который находится на улице с температурой 85-100 градусов и, проходя через теплообменники, передает свое тепло воде, на выходе из теплообменников температура конденсата 40-90градусов. Также стоят два резервных насоса №1, №2 рис. 8 подачи конденсата после теплообменников в бак конденсата на улицу. В зимний период работаем на насосе подачи конденсата №3, который запускается с блока на нем две кнопки зеленая - «пуск» и красная - «стоп», индикационная зеленая лампочка работы насоса находится в шкафу управления насосами №1, №2 рис. 10 подачи охлажденного конденсата в бак. В случае выхода из строя насоса №3 перекрываются затворы №1, №2 (рис.9), №4 (рис.8), открываются затвор №3 (рис. 9) и затворы до и после одного из насосов конденсата (№1, №2 рис.№8), на который переходим работать."},{"type":"image","src":"images/doc1_009.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 8"},{"type":"text","text":"Рис. № 9"},{"type":"image","src":"images/doc1_010.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_011.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 10"},{"type":"text","text":"1.4.2 Бак ХВО"},{"type":"text","text":"Бак ХВО служит как накопительная емкость. В баке установлена система (САУ) система автоматического управления (рис. № 11). Которая измеряет уровень наполнения бака и управляет потоком воды на заполнение бака ХВО, насосом подачи воды с бака ХВО в деаэратор и циркуляцией воды с бака ХВО через теплообменники."},{"type":"text","text":"На рисунке № 11 изображена панель управления (САУ). Система отслеживает три уровня воды в баке."},{"type":"text","text":"Первый самый минимальный аварийный уровень напротив буквы «А», пока не загорится индикатор, не смогут запуститься насосы подачи воды в деаэратор."},{"type":"text","text":"И два рабочих уровня напротив буквы «Р», нижний и верхний."},{"type":"text","text":"На панели также имеются кнопки управления:"},{"type":"text","text":"- «авт» система работает в автоматическом режиме"},{"type":"text","text":"- «пуск», «стоп» система управляется в ручном режиме"},{"type":"text","text":"и индикаторы:"},{"type":"text","text":"- индикатор автоматического режима"},{"type":"text","text":"- индикатор «работа»"},{"type":"text","text":"- индикатор «сеть» наличие питания"},{"type":"text","text":"- индикатор «авария» неисправность (САУ)"},{"type":"image","src":"images/doc1_012.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 11"},{"type":"text","text":"Система работает так. В бак хво набирается вода, когда она доходит до уровня «А» то можно запустить насос подачи воды из бака в деаэратор затем вода доходит до нижнего рабочего уровня, который соответствует половине бака, при загорании верхнего рабочего уровня срабатывает электромагнитный клапан (см. схему водоподготовки), перекрывающий подачу воды в бак и запускает систему циркуляции, подающую воду из бака ХВО через теплообменники обратно в бак при помощи циркуляционного насоса рис.13. Тем самым подогревая воду еще сильнее. Как только погаснет нижний рабочий уровень САУ отключит циркуляцию, откроет эл. маг. клапан и бак будет наполняться снова."},{"type":"text","text":"1.4.3 Подача воды из бака ХВО в деаэратор."},{"type":"text","text":"Из бака ХВО вода подается одним из насосов (см. схему) в деаэратор через систему клапанов (рис № 12). Вода в деаэратор подается через два электромагнитных клапана V1 и V2. Клапана открываются в зависимости от уровня воды в деаэраторе. Максимальный уровень 80% - оба клапана закрыты. При опускании уровня до 79% открывается клапан V1 и на манометре должно быть давление 0,5 бар. При опускании уровня до 76% открывается клапан V2 (оба клапана открыты) давление на манометре должно быть 0,9-1 бар. Если уровень в деаэраторе меньше 76%, а давление на манометре меньше 0,9 бар – это говорит о том, что неисправен один из клапанов. В этом случае имеется шаровой кран «байпас», который открывает оператор. При открытии этого крана нужен постоянный контроль во избежание переполнения деаэратора. При достижении уровня 77% клапан V2 закрывается, а при достижении уровня 80% закрывается клапан V1."},{"type":"text","text":"При отсутствии воды в баке ХВО или какой-либо неисправности с баком, подающими насосами, допускается прямая подача воды после системы ХВО в деаэратор (см. схему)."},{"type":"image","src":"images/doc1_013.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 12"},{"type":"text","text":"1.4.4 Управление насосами подачи воды из бака ХВО в деаэратор и подачи охлажденного конденсата после теплообменников в бак конденсата."},{"type":"text","text":"На подаче воды из бака ХВО в деаэратор стоят два насоса включенных параллельно основной и резервный рис. №13. Эти насосы управляются с помощью ящика управления рис № 14."},{"type":"image","src":"images/doc1_014.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 13"},{"type":"image","src":"images/doc1_015.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 14"},{"type":"text","text":"В ящике находится переключатель на пять положений:"},{"type":"text","text":"0 – насосы выключены"},{"type":"text","text":"1 – автоматический режим насосы работают по очереди по заданному промежутку времени"},{"type":"text","text":"2 – работает насос 1"},{"type":"text","text":"3 – работает насос 2"},{"type":"text","text":"4 – работают оба насоса."},{"type":"text","text":"Насосы перекрываются запорными задвижками, нужно следить, чтобы задвижки на работающих насосах были открыты."},{"type":"text","text":"Точно такая же система управления и на насосах подачи охлажденного конденсата в бак, после пластинчатого теплообменника."},{"type":"text","text":"1.5 Деаэратор."},{"type":"text","text":"Деаэратор служит для удаления кислорода из воды. Умягченная вода подается из бака ХВО с температурой 35-40 градусов. Также в деаэратор подается пар с котлов. Вода подогревается паром и нагревается до температуры 105 градусов. При нагревании из воды убирается кислород."},{"type":"text","text":"Рабочее давление при этом в деаэраторе составляет 0,22-0,29 бар. Показание давления и температуры можно отслеживать по манометру и термометру установленных на деаэраторе (рис № 15). Также имеется водоуказательная колба с поплавком, по которому визуально определяем уровень наполнения деаэратора и сравниваем его с показаниями на дисплее."},{"type":"image","src":"images/doc1_016.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 15"},{"type":"text","text":"Управление деаэратором происходит щитом управления, на котором находится дисплей."},{"type":"text","text":"На дисплее (Рис. № 16) показаны уровень воды в деаэраторе и давление. Оператору каждый раз при обходе котельной нужно проверять соответствие показаний на дисплее, показаниям на механическом манометре давления, и соответствие показаний уровню жидкости в колбе."},{"type":"image","src":"images/doc1_017.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 16"},{"type":"text","text":"Еще в деаэратор подается хим. реагент «160», для уменьшения коррозии в котлах. Реагент подается насосом дозатором из бочки (см. рис. № 15), насос подает хим. раствор только тогда, когда открыт один из клапанов системы подачи воды в деаэратор V1 и V2. Раствор наводится в бак в пропорции 1/9, одна часть химии, 9- воды умягченной воды"},{"type":"text","text":"Далее вода из деаэратора подается питательными насосами в котлы. На каждый котел используется по два насоса один основной и резервный. На всос насоса подается хим. раствор «710», для уменьшения коррозии трубопроводов. Раствор также подается насосом дозатором, который включается только при работе одного из питательных насосов котлов. Раствор наводится в бак в пропорции 1/9, одна часть химии, 9- воды умягченной воды."},{"type":"text","text":"В баки растворы «710», «160» заливать только с помощью контрольной канистры: гидрохим заливается по метке, остальное – вода после третьей ступени ХВО. Делается запись в журнале, количество залитых канистр."},{"type":"text","text":"2. ГРУ"},{"type":"image","src":"images/doc1_018.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис.№17"},{"type":"text","text":"ГРУ – газораспределительная установка, служит для подачи газа к котлам №1, №2 и настенному котлу ГВС и аварийного отключения подачи газа. Наличие газа в магистрали контролируется манометром М1 (рис17). Давление на входе составлять 6 Бар. ГРУ осуществляет понижение давления от 6 Бар до 0,6 Бар для работы котлов. Пути прохождения газа указаны красными стрелками. Газ подаётся через электромеханический клапан К1 (рис17, рис 17а), который служит для аварийного отключения подачи газа в котельную при срабатывании датчиков наличия природного газа и СО2."},{"type":"text","text":"Рис.№17а"},{"type":"image","src":"images/doc1_019.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"На котлы №1 и №2 газ подаётся через соответствующие ПЗК. ПЗК – предохранительно-запорный клапан, который срабатывает при исчезновении газа, либо при превышении допустимого значения."},{"type":"image","src":"images/doc1_020.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис.№17б"},{"type":"text","text":"Правильное взведение клапана показано на рисунке №17в."},{"type":"image","src":"images/doc1_021.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис.№17в"},{"type":"text","text":"На настенный газовый котёл газ подаётся через специальный клапан, указанный на рисунке №17г. Клапан срабатывает при исчезновении давления."},{"type":"image","src":"images/doc1_022.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис.№17г"},{"type":"text","text":"3. Система автоматического отключения подачи газа"},{"type":"text","text":"Так же имеется система автоматического отключения подачи газа в котельную. Она включает в себя:"},{"type":"text","text":"1. Щит управления (рис №18)."},{"type":"text","text":"2. Пульт управления индикации и сброса аварий (рис №18)"},{"type":"text","text":"3. Пять датчиков загазованности"},{"type":"text","text":"4. Электромеханический клапан для отключения подачи газа в котельную"},{"type":"image","src":"images/doc1_023.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис.№18"},{"type":"text","text":"Датчики установлены у котла №1 и №2 по две штуки, внизу и над котлом под крышей, рисунки №18а, №18б. Срабатывают на СО2 и природный газ. Настенный котёл имеет один датчик под потолком. Доступ ко всем датчикам имеется."},{"type":"image","src":"images/doc1_024.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_025.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис.№18а                            Рис.№18б"},{"type":"text","text":"Аварийное срабатывание выведено на пульт сигнализации в диспетчерскую. Обозначается как «газ» и «пожар»."},{"type":"text","text":"При срабатывании сигнализации диспетчер (оператор) должен явиться в котельную, посмотреть какой из датчиков сработал и на каком котле. При аварии индикация датчика будет мигать зелёным либо красным светом. Затем нужно сбросить аварию на пульте управления (маленький блок над щитом управления), подождать пока система не встанет в дежурный режим, то есть, когда закончится опрос датчиков и перестанут мигать светодиоды на них. Когда система встанет в дежурный режим, то светодиоды перестанут мигать, и будут гореть только верхние зелёным светом."},{"type":"text","text":"Если система не встаёт в дежурный режим и сработала снова, то нужно посмотреть по какому датчику идёт сработка. Далее отключить автомат в щите управления, добраться до датчика, подуть на него, тем самым убрать остатки газов. Затем включить автомат в щите и ждать постановки системы в дежурный режим."},{"type":"text","text":"3.1 Последовательность действий для взведения клапанов:"},{"type":"text","text":"1. Перекрываем вентиля №1, №2, №3, №4. (рис№17)."},{"type":"text","text":"2. Сбрасываем ошибку на пульте управления, нажав на кнопку «сброс» (рис№18)."},{"type":"text","text":"3. Взводим электромагнитный клапан К1 как показано на рис№17а."},{"type":"text","text":"4. Взводим клапана ПЗК-1 и ПЗК-2 в положения, указанные на рис№17в, предварительно выдернув штоки клапанов на себя."},{"type":"text","text":"5. Взводим в рабочее положение клапан К2 (рис№17г). Для этого сбрасываем остаточное давление при помощи вентиля №5. Далее выкручиваем металлическую заглушку (рис№17г) и резко дёргаем её на себя и закручиваем обратно."},{"type":"text","text":"6. Закрываем вентиль №5."},{"type":"text","text":"7. Медленно открываем вентиль №1 и подаём газ."},{"type":"text","text":"8. Так же медленно открываем вентиля №2, №3, №4, чтобы не сработали ПЗК-1 и ПЗК-2."},{"type":"text","text":"9. Запускаем котлы."},{"type":"text","text":"Сделать запись в сменном журнале с указанием времени, датчика, который сработал и на каком котле!!!"},{"type":"text","text":"4. Котлы."},{"type":"text","text":"В котельной используются два жаротрубных паровых котла производительностью 4 тонны пара в час. Работают котлы на природном газе. Расчетное давление 20 бар. Расчетная температура 215 градусов."},{"type":"text","text":"4.1. Устройство котла."},{"type":"text","text":"Котел представляет собой бочку, в которую врезана одна большая труба и много маленьких. С одной стороны большой трубы прикреплена газовая горелка, которая подает пламя в эту трубу."},{"type":"text","text":"С другой стороны, большая труба соединена с маленькими, по которым уходят дымогарные газы с большой температурой. Тем самым нагрев воды в котле происходит большой трубой, в которой горит пламя и маленькими трубами, по которым идут уходящие газы."},{"type":"text","text":"Уходящие газы, проходя через экономайзер, сбрасываются в атмосферу по отводящим трубам."},{"type":"text","text":"Экономайзер служит для подогрева питательной воды в котел. Вода с деаэратора подается 105 градусов, проходя через экономайзер, еще подогревается уходящими газами, температура которых 160-200 градусов."},{"type":"text","text":"Как говорилось выше котел это бочка, в которую подается вода - там она доводится до кипения и выходит пар. На котле имеется выходной вентиль пара. Датчики уровня воды, датчик давления, датчик электропроводимости, смотровые окна по которым оператор смотрит соответствие уровня воды реальное с показанием уровня на дисплее, механический манометр, по которому оператор также смотрит соответствие реального давления давлению на экране монитора. Эти смотровые окна должны чиститься один раз в смену."},{"type":"text","text":"4.2 Чистка индикатора уровня воды на котлах при помощи продувки"},{"type":"text","text":"Плохое качество считывания уровня является следствием образования налета на внутренней поверхности индикационного прибора. Индикатор уровня нужно чистить каждый день при помощи продувки."},{"type":"text","text":"При этом нужно придерживаться следующих шагов (рис.19):"},{"type":"text","text":"Закрыть верхний (1) и нижний (2) запорный клапаны."},{"type":"text","text":"Открыть спускной клапан (3)."},{"type":"text","text":"2раза открыть верхний запорный клапан (1) на 1-2секунды (нужно повернуть на ½ оборота влево) и снова закрыть."},{"type":"text","text":"2раза открыть нижний запорный клапан (2) на 1-2секунды (нужно повернуть на ½ оборота влево) и снова закрыть."},{"type":"text","text":"Осторожно! Для бережного обращения со стеклами нужно проводить только кратковременную продувку (примерно на 2 секунды). Во избежание закрывания автоматического шарового затвора запорные клапаны (1) и (2) и спускной клапан (3) нужно открывать очень медленно. Если по неосторожности запорные клапаны открыли слишком быстро и автоматический шаровый затвор закрылся, его можно снова открыть. Для этого нужно полностью закрыть запорные клапаны (1) и (2) и снова медленно их открыть."},{"type":"text","text":"После продувки спускной клапан (3) снова закрыть"},{"type":"text","text":"Опасно! Все аппараты, находящиеся под давлением и высокой температурой, являются объектами высокой опасности. Просочившаяся горячая среда может послужить причиной несчастного случая."},{"type":"text","text":"Рис. № 19"},{"type":"image","src":"images/doc1_026.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Для долговечной работы котла предусмотрено два вида продувок. Продувки нужны для удаления шлама из котла. Первая это непрерывная продувка, которая управляется автоматически в зависимости от показаний датчика электропроводимости. Чем больше электропроводимость, тем больше шлама в воде и тем сильнее открывается клапан см. рис. № 19. Вторая продувка – это периодическая, которая в автоматическом режиме включает пневмоклапан см. рис. № 20 - через который давлением в котле выдувается шлам. Клапан срабатывает один раз в час на 4-6 секунд."},{"type":"image","src":"images/doc1_027.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 20"},{"type":"text","text":"Для безопасности на котле установлены предохранительно сбросные клапана (ПСК) пружинного типа. При превышении давления в котле на 10% клапана срабатывают."},{"type":"text","text":"4.3 Запуск котла."},{"type":"text","text":"1.Предварительно проверить правильность и плотность подключения внутренних и внешних контактных соединений датчиков и приборов, соответствие их электрических и монтажных схем."},{"type":"text","text":"2.Включить эл. питание щитов систем управления котлом «LOOS» - LBC, автоматики деаэратора и барботера - LSC, управления общекотельным оборудованием путем перевода переключателя питания щитов в положение «ВКЛ». Проверить наличие питания на горелке и щите LBC, LSC и общекотельного оборудования. Происходит загрузка и диагностика внутренней памяти контроллера, на сенсорной панели LBC появляется изображение котла см. рис. 21."},{"type":"text","text":"На сенсорной панели LSC появляется изображение активированных окон деаэратора, котлов и барботера см. рис.22"},{"type":"text","text":"На панели оператора котельного оборудования изображение активных кнопок управления клапанами и насосами;"},{"type":"image","src":"images/doc1_028.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_029.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 21                                        Рис. № 22"},{"type":"text","text":"3. На сенсорной панели оператора LSC путем прикосновения пальцем руки к окну с изображением барботёра открыть его и установить регулятор температуры по охлаждению конденсата в автоматический режим управления электромагнитным клапаном подачи исходной воды в барботёр. см. рис.23 и 24."},{"type":"image","src":"images/doc1_030.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_031.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 23                                          Рис. № 24"},{"type":"text","text":"4. Выйти из окна управления барботёром путем прикосновения пальцем руки к «кнопке» с изображением стрелки, находящейся в левой верхней зоне экрана и открыть окно с изображением деаэратора. Установить регулятор уровня и сброса воды с деаэратора в автоматический режим управления соответствующими электромагнитными клапанами как указанно на рис. 25-26."},{"type":"image","src":"images/doc1_032.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_033.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 25                                       Рис.№ 26"},{"type":"text","text":"5.Включить блок управления деаэратором путем прикосновения пальцем руки к «кнопке» «ON» находящейся в правой нижней зоне экрана;"},{"type":"text","text":"6. Нащите общекотельной автоматики на сенсорной панеле оператора прикоснуться к «кнопке» - «Клапан подпитки накопительного бака», в открывшимся окне выбрать функцию автоматического режима управления электромагнитным клапаном подачи хим-очищенной воды в бак накопитель. Нажать на «кнопку» - «Меню», и выйти из окна управления уровнем воды в накопительном баке. После заполнения бака накопителя подготовить к запуску питательные насосы деаэратора, переключателями, смонтированными на распределительном щите управления насосами, выбрать поочередно следующие режимы - насос №1 - «АВР», насос №2 -«АВР», включается насос №1, насос №2 остается в резерве АВР."},{"type":"text","text":"7. Включить блок управления котлом как указанно на рисунках 27-28."},{"type":"image","src":"images/doc1_034.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_035.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 27                                       Рис. № 28"},{"type":"text","text":"8. При появлении неисправности, на сенсорной панели LBC высвечивается звуковой сигнал и появляется сообщение об аварии или ошибке контроллера, ликвидировать сообщение необходимо как указанно на рисунке 29."},{"type":"text","text":"9. После исправления неисправности снять блокировку котла посредством поворота клавишей переключателя снятия блокировки вправо до упора с возвратом в исходное положение, символ аварии котла исчезает."},{"type":"image","src":"images/doc1_036.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 29"},{"type":"text","text":"10. Перед пуском котла необходимо проверить режим работы котла и выбрать обычный режим работы или поддержание горячего резерва. Проверить уровень воды в котле. Регулирование уровня, если оно еще не находится в автоматическом режиме, установить в это положение путём прикосновения пальцем руки на «кнопку» как отображено на рис. 30-33. Уставка регулирования LM должна составлять 55-60 %. При необходимости, вручную открыть нижний дренаж посредством пневмоклапана шламоудаления для уменьшения уровня или включить питательный насос в ручном режиме путем прикосновения пальцем к «кнопке» для увеличения уровня, как указанно на рис. 34-35."},{"type":"image","src":"images/doc1_037.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_038.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 30                                     Рис. № 31"},{"type":"image","src":"images/doc1_039.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_040.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 32                                     Рис. № 33"},{"type":"text","text":"и проследить за дросселированием питательных насосов, т.е. если давление в котле отсутствует или ниже 3 bar, то для снятия кавитации приоткрыть задвижку от закрытого положения на выходных патрубках насоса на 0,5-1 оборота. При давлении в котле выше 3 bar задвижки открыть полностью;"},{"type":"image","src":"images/doc1_041.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_042.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. №34                                         Рис. № 35"},{"type":"text","text":"11. При запуске котла, задвижки по воде в котел должны быть закрыты. Переключить кнопкой питательные насосы в автоматический режим управления путем прикосновения пальцем руки к «кнопке» как отображено на рис. 36. Проверить работу питательных насосов. В работе должен находиться один насос. После включения насосов открыть задвижки на нагнетании питательных насосов"},{"type":"image","src":"images/doc1_043.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 36"},{"type":"text","text":"12. Проверить работу регулирующего клапана продувки котла в ручном режиме управления, путем открытия установки в среднее положение и закрытия. Переключить регулятор проводимости котловой воды в автоматический режим управления путем прикосновения пальцем руки к «кнопке» как указанно на рис. 37-40. Уставка регулирования СМ должна составлять 3200 - 4000 мS/cm."},{"type":"image","src":"images/doc1_044.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_045.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 37                                Рис. № 38"},{"type":"text","text":"13. Проверить работу пневмоклапана шламоудаления с котла в ручном режиме управления путем его открытия. Переключить регулятор шламоудаления в автоматический режим управления, как указанно на рис. 41, отображено на рис. 42. Уставка настройки периода TP составляет 1h, а длины импульса TI -4-6 sec."},{"type":"image","src":"images/doc1_046.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_047.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. №39                                      Рис. № 40"},{"type":"image","src":"images/doc1_048.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_049.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 41                               Рис. № 42"},{"type":"text","text":"14.Произвести розжиг котла."},{"type":"text","text":"15.На деаэраторе проверить режим работы регулятора уровня воды и давления пара. Регулятор уровня установить в автоматический режим управления питательным соленоидным клапаном, как указанно на рис. 43-44, отображено на рис. 45."},{"type":"image","src":"images/doc1_050.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_051.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 43                              Рис. № 44"},{"type":"image","src":"images/doc1_052.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. №45"},{"type":"text","text":"4.3.1 Запуск котла без давления."},{"type":"text","text":"1. Из холодного состояния запускать котел рекомендуется только в ручном режиме. Включение горелки в ручном режиме осуществляется с контроллера котла нажатием на «кнопку», как указанно на рис. 46, 46а, 47, отображено на рис. 48."},{"type":"image","src":"images/doc1_053.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_054.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 46                               Рис. № 46а"},{"type":"text","text":"В случае отсутствий ошибок по безопасности котла и снятия блокировки защиты, горелка в ручном режиме регулирования, запускается и работает на минимальной нагрузке."},{"type":"image","src":"images/doc1_055.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_056.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 47                              Рис. № 48"},{"type":"text","text":"2. Открытие парозапорного вентиля на выходе из котла может производится в автоматическом или ручном режимах. Для автоматического режима необходимо управление задвижкой парозапорного вентиля из ручного режима перевести в автоматический, как указанно на рис. 49, 50, отображено на рис. 51."},{"type":"image","src":"images/doc1_057.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 49"},{"type":"image","src":"images/doc1_058.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_059.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 50                                 Рис. № 51"},{"type":"text","text":"3.При достижении давления пара в котле равном 2,5 кгс/см2 нагрузку котла следует увеличить на 15 %. При достижении давления пара в котле 4 кгс/см2 нагрузку котла увеличить до 60 % от номинальной."},{"type":"text","text":"4.         Для ручного режима необходимо управление задвижкой парозапорного вентиля из автоматического режима перевести в ручной. При отсутствии давления в котле задвижку парозапорного вентиля открыть на 50 %. При достижении давления пара в котле равном 4 кгс/см2 открыть полностью."},{"type":"text","text":"5.В период подъёма давления в котле необходимо постоянно контролировать уровень воды (поле 4, второй строки основного изображения см. рис. 52). Из-за теплового расширения воды внутри котла может появиться предупредительная сигнализация предупреждения перелива воды при 85%. В этом случае через быстродействующую арматуру удаления шлама путем фиксирования кнопки находящейся на пневмореле мембранного клапана (нажмите и проверните на пол оборота по часовой стрелке), необходимо спускать воду до среднего уровня воды в стеклах. На мониторе панели оператора показание уровня в котле должно установиться в пределах 45-55 % (рис.52)"},{"type":"text","text":"6.При достижении номинального давления пара в котле необходимо плавно открыть паровые вентиля на систему отопление (теплообменники) и производство, регулятор давления включить в автоматический режим управления горелкой, как указанно на рис. 46, 47, отображено на рис. 48. При этом горелка выйдет на максимальный режим, и в дальнейшем будет поддерживать заданное давление."},{"type":"text","text":"7. Если все регуляторы работают в автоматическом режиме то на сенсорной панели LBC в изображении котла, на строке 1 в поле основного изображения 5 происходит изменение символа ручного управления (рука) на символ автоматического регулирования (поле 5, строка 1 основного изображения на панели оператора см. рис. 52). В нижней строке активируются символы устройства пуска, готовности и снижения нагрузки котла, как изображено на рис. 53, 54."},{"type":"image","src":"images/doc1_060.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 52"},{"type":"image","src":"images/doc1_061.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_062.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 53                               Рис. № 54"},{"type":"text","text":"Давление газа перед котлом, перед регулятором давления газа горелки, должно составлять 280-320 мбар, после стабилизатора давления - 45-60 мбар."},{"type":"text","text":"4.3.2 Кратковременная остановка котла с активированным устройством пуска, готовности и снижения нагрузки."},{"type":"text","text":"Автоматический режим. (действует только если все регуляторы работают в автоматическом режиме – горит символ автоматического регулирования (поле 5, строка 1 основного изображения на панели оператора см. рис. 52))."},{"type":"text","text":"Для останова котла по техническим причинам необходимо нажать на символ, изображенный в нижней строчке слева на сенсорной панели LBC, как указанно на рис. 54."},{"type":"text","text":"При нажатии этого символа в управляемом режиме горелка перейдет в положение малой нагрузки, все регуляторы кроме регулятора мощности останутся в выбранном положении. Через 120 секунд горелка отключится."},{"type":"text","text":"Ручной режим. (действует только если все регуляторы работают в ручном режиме – горит символ ручного (рука) регулирования (поле 5, строка 1 основного изображения на панели оператора см. рис. 52))."},{"type":"text","text":"Выключение горелки в ручном режиме осуществляется с контроллера котла нажатием на «кнопку OFF», как указанно на рис. 54a, 54b."},{"type":"image","src":"images/doc1_063.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_064.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 54a                              Рис. № 54b"},{"type":"text","text":"4.3.3 Включение котла после кратковременной остановки с активированным устройством пуска, готовности и снижения нагрузки."},{"type":"text","text":"Автоматический режим. (действует только если все регуляторы работают в автоматическом режиме – горит символ автоматического регулирования (поле 5, строка 1 основного изображения на панели оператора см. рис. 52))."},{"type":"text","text":"Для включения котла после кратковременной остановки необходимо нажать на символ, изображенный в нижней строчке справа на сенсорной панели LBC, как указанно на рис. 53."},{"type":"text","text":"При нажатии этого символа в управляемом режиме розжига котла горелка после ее розжига переходит в положение малой нагрузки и через 30 секунд включается регулятор мощности котла, и горелка начинает стремиться выходить на максимальную мощность пока актуальное давления пара в котле не сравняется с заданной уставкой - bar."},{"type":"text","text":"Ручной режим. (действует только если все регуляторы работают в ручном режиме – горит символ ручного (рука) регулирования (поле 5, строка 1 основного изображения на панели оператора см. рис. 52))."},{"type":"text","text":"Включение горелки в ручном режиме осуществляется с контроллера котла нажатием на «кнопку ON», как указанно на рис. 54c, 54d."},{"type":"image","src":"images/doc1_065.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_066.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 54c                               Рис. № 54d"},{"type":"text","text":"В случае отсутствий ошибок по безопасности котла и снятия блокировки защиты, горелка в ручном режиме регулирования, запускается и работает на минимальной нагрузке."},{"type":"text","text":"4.3.4 Выключение котла с активированным устройством пуска, готовности и снижения нагрузки,"},{"type":"text","text":"1.Выключить котел (см. Кратковременный останов котла)."},{"type":"text","text":"2.В ручном режиме управления закрыть котловой паровой вентиль."},{"type":"text","text":"3.Выключить блок управления котлом, как указанно на рис. 55, 56."},{"type":"image","src":"images/doc1_067.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_068.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 55                                       Рис. № 56"},{"type":"text","text":"4.Выключить главный переключатель питания в шкафу управления котлом."},{"type":"text","text":"5.Закрыть задвижки до и после регулирующего клапана питательной воды в котел."},{"type":"text","text":"6.Закрыть шибер в газоходе котла."},{"type":"text","text":"7.При длительном останове котла в зимнее время необходимо слить воду с экономайзера."},{"type":"text","text":"8.Закрыть паровой вентиль на выходе из котельной."},{"type":"text","text":"9.Закрыть шаровой кран по газу на входе в котельную. Открыть продувочные свечи на внутреннем газопроводе."},{"type":"text","text":"4.3.5 Останов и запуск котла после аварии."},{"type":"text","text":"При аварийной отработке автоматики защиты котла, например, автоматизированной горелки, происходит блокировка защиты, регуляторы уровня и проводимости остаются в работе."},{"type":"text","text":"Переключатель управления горелкой, изображенный на сенсорной LBC см. рис. 46а, а режим регулирования мощности котла автоматически переводится в ручной-см. рис. 48."},{"type":"text","text":"Включается акустический сигнал оповещения аварии."},{"type":"text","text":"Необходимо выяснить причину аварийного останова горелки. Коды аварии выводятся на экран менеджера горения. После устранения причины аварии горелки, необходимо разблокировать менеджер горения."},{"type":"text","text":"На горелочном менеджере горения W-FM-50, нажать кнопку «Enter»-«Деблокировка менеджера горения»."},{"type":"image","src":"images/doc1_069.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 57"},{"type":"text","text":"При появлении неисправности, на сенсорной панели LBC высвечивается окошко с сообщением, сообщение первого приоритета сопровождается прерывистым или непрерывным акустическим сигналом. Выключить звуковой сигнал и квитировать сообщение как указано на рис. 57."},{"type":"text","text":"Снять блокировку котла посредством поворота клавишей переключателя снятия блокировки вправо до упора с возвратом в исходное положение, символ аварии котла исчезает."},{"type":"text","text":"Розжиг котла после аварии необходимо проводить в ручном режиме аналогично запуску котла без давления."},{"type":"text","text":"5. Магистраль пара."},{"type":"text","text":"Пар из обоих котлов подается в магистраль пара в котельной см. рис. № 58. Пар проходит через редуцирующий клапан, с каждой стороны редуцирующего клапана установлены перекрывающие вентиля и манометры. При неисправности редуцирующего клапана в магистрали имеется байпасная линия для обхода редуцирующего клапана. Так же после узла редуцирования на магистрали установлен предохранительный клапан, который срабатывает при превышении давления в магистрали выше 17 бар. далее магистраль уходит в цех. В цехе у ворот на упаковочной линии на магистрали установлен клапан, который перекрывает подачу пара на автоклавы."},{"type":"text","text":"Перед выходом магистрали из котельной от нее имеется отвод пара на теплообменники отопления завода."},{"type":"image","src":"images/doc1_070.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 58"},{"type":"text","text":"6. Система отопления."},{"type":"text","text":"Отопление завода производится за счет теплообменников, в которых происходит нагрев воды, циркулирующей по системе отопления паром. Резервный источник на отопление – это электрокотлы."},{"type":"text","text":"Пар от магистрали подается на теплообменники через перекрывной вентиль и регулирующий вентиль (см. рис. № 59) в теплообменнике происходит нагрев воды. Пар при обогреве воды конденсируется и подается в деаэратор."},{"type":"text","text":"Отопление работает в автоматическом режиме. В магистрали выхода воды после теплообменников установлен датчик температуры, сигнал с которого приходит в контроллер, расположенный в щите управления см. рис. № 59."},{"type":"image","src":"images/doc1_071.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 59."},{"type":"text","text":"На контроллере отображается реальное значение температуры воды и установленное (см. рис. № 60). Устанавливается температура с помощью кнопок со стрелочками. После того как ввели значение температуры нужно три раза нажать кнопку «прог.», чтобы сохранить значение."},{"type":"image","src":"images/doc1_072.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc1_073.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 60                               Рис. № 61"},{"type":"text","text":"Система работает так, допустим, у нас выставлено значение температуры 50 градусов. Датчик температуры измеряет температуру воды. Сигнал с датчика поступает на контроллер, который в свою очередь сравнивает значение показания датчика с установленным значением и дает сигнал на открытие или закрытие регулирующего вентиля. Чем ниже температура от установленной, тем больше открывается регулирующий вентиль и тем больше подается пара на обогрев воды."},{"type":"text","text":"При сбое в работе системы отопления (не происходит нагрев) нужно перезагрузить контроллер отопления, для этого нужно открыть щит управления и выключить вводной автомат, подождать тридцать секунд и включить его снова см. рис. № 61."},{"type":"text","text":"Далее нагретая вода подается в коллектор распределения по контурам отопления см. рис № 62."},{"type":"text","text":"С коллектора отопления вода подается по пяти контурам отопления:"},{"type":"text","text":"•котельная"},{"type":"text","text":"•корпус АБК (административно бытовой корпус)"},{"type":"text","text":"•Регистры (батареи в цехах)"},{"type":"text","text":"•вентиляция котельной"},{"type":"text","text":"С каждого контура отопления остывшая вода возвращается в коллектор обратки (см. рис. №62), с которой снова подается на теплообменники для нагрева. Циркуляция воды осуществляется циркуляционным насосом, находящимся у теплообменников (рис.№59)."},{"type":"text","text":"Давление в системе отопления должно быть 2-3 бар. Контроль давления и температуры осуществляется по механическим манометрам и термометрам, установленным на каждом контуре отопления в рампах подачи и обратки. В коллектор обратки осуществляется подпитка системы водой, если давление ниже установленного. Подпитка производится хим.очищенной водой после третьей ступени ХВО (см. схему водоподготовки котельной)."},{"type":"text","text":"Также излишнее давление можно сбросить в канализацию, путем открытия крана, находящегося под коллектором обратки отопления."},{"type":"image","src":"images/doc1_074.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 62"},{"type":"text","text":"7. Система горячего водоснабжения."},{"type":"text","text":"Горячее водоснабжение АБК осуществляется настенным газовым котлом см. рис. № 63."},{"type":"image","src":"images/doc1_075.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 63."},{"type":"text","text":"Смысл нагрева воды точно такой же, как нагрев воды на отопление, только вода нагревается не паром, а более горячей водой (прямой водой), которая циркулирует через газовый котел и накопительный бак по змеевику, в котле вода нагревается, а в баке передает свое тепло воде горячего водоснабжения. Следовательно, накопительный бак является своеобразным теплообменником. Вода из накопительного бака подается на АБК циркуляционным насосом и возвращается затем обратно в бак, тем самым вода в трубах всегда остается горячей."},{"type":"text","text":"При отборе горячей воды в накопительный бак подается холодная вода, она подается в нижнюю часть бака и снова подогревается."},{"type":"text","text":"8. Управление настенным газовым котлом."},{"type":"text","text":"Оператор смотрит за давлением в системе горячего водоснабжения, оно не должно превышать 4 бар и быть меньше 2 бар. Если вода давлением меньше двух бар следует заменить фильтр тонкой очистки. Так же оператор следит за давлением прямой воды в настенном котле, оно не должно превышать 2 бар и быть меньше 1 бара. Если давление меньше 1 бара, то нужно подпитать котел водой."},{"type":"text","text":"Перед запуском котла необходимо убедиться в наличие давления газа перед котлом. Для этого необходимо посмотреть манометр на ГРУ – указан на рисунке 64. Манометр должен показывать примерно 2,5 кПа."},{"type":"image","src":"images/doc1_076.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 64"},{"type":"text","text":"Малый котел управляется с помощью универсальной горелки UBA. Панель управления данной горелки представлена на рис. 65."},{"type":"image","src":"images/doc1_077.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 65"},{"type":"text","text":"1. Дисплей.2. Кнопка “service”.3. Кнопка “reset”.4. Выключатель насоса.5. Температура среды в котле.6. Температура горячего водоснабжения.7. Регулятор тепловой мощности.8. Переключатель очистки дымохода.9. Перемычка 11 кВт."},{"type":"text","text":"При включении котла с помощью выключателя на панели, после диагностики на дисплее должны загореться символы."},{"type":"text","text":"Символ означает, что котел находится в рабочем режиме и горелка пока выключена."},{"type":"image","src":"images/doc1_078.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Символ означает, что котел находится в рабочем режиме и горелка включена."},{"type":"image","src":"images/doc1_079.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Символ означает, что необходимо произвести сброс котла нажав и удержав кнопку “reset” нажатой 5 с для возврата UBA в режим резерва."},{"type":"image","src":"images/doc1_080.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Появление других символов означает ошибку. В этом случае необходимо зафиксировать ошибку на фото, нажать и удерживать кнопку “reset” нажатой 5 с для сброса ошибки."},{"type":"text","text":"В случае если ошибка не исчезает необходимо вызвать слесаря или энергетика."},{"type":"text","text":"9. Конденсат."},{"type":"text","text":"Конденсат образуется в процессе запаривания кирпича. Из автоклавов конденсат отводится автоматически, с помощью конденсатоотводчиков, в конденсатную линию, затем в бак конденсата у автоклавов (см. рис. № 65). Из этого бака конденсат с помощью насоса подается в «Бак конденсата на улице № 1», из этого бака конденсат циркулирует через теплообменник для нагревания хим. очищенной воды, циркуляция происходит насосами, установленными у теплообменников. С «Бака конденсата на улице № 1» конденсат подается на технологию в баки малого и большого смесителей, в зависимости с какого бака пришел сигнал на заполнение. При переполнении «Бака конденсата на улице № 1» излишки конденсата стекают в «Бак конденсата на улице № 2», там конденсат охлаждается и сливается в канализацию."},{"type":"image","src":"images/doc1_081.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рис. № 65"},{"type":"text","text":"10. Обязанности диспетчера."},{"type":"text","text":"Диспетчер докладывает нач. смены о прибытии на работу. Получает информацию от предыдущего диспетчера о состоянии работающего оборудования. Прибывший на смену диспетчер принимает смену, а предыдущий диспетчер сдаёт смену совместно, начиная с осмотра оборудования:"},{"type":"text","text":"Зайти в помещение скважины и убедиться в нормальной работе скважинного оборудования. В случае, каких-либо неполадок, принять меры к их устранению."},{"type":"text","text":"Зайти в котельную и убедиться в нормальной работе установки химводоподготовки: работа ступеней ХВО по информационному табло, которое в нормальном режиме светится, идёт чередование цифр, букв и не мигает. Наличие давления воды в трубопроводе определяем по показаниям манометров на водопроводе. Давление д/быть 6 Атм. на вводе после редукционного клапана и не ниже 4 Атм. после фильтров. В случае большего перепада, необходимо прочистить сетчатый фильтр, если давление не возросло, заменить оба фильтра тонкой очистки-при необходимости. Проверить наличие соли в баке-солерастворителе. Объем соли должен быть выше уровня воды в баке."},{"type":"text","text":"Убедиться в нормальной работе циркуляционных насосов на химочищенной воде, теплообменниках, подаче воды на деаэратор и подачи конденсата на технологию. Убедиться в работе деаэратора по показаниям КИПиА, сравнить с данными на информационном табло щита управления деаэратором. Заполнение деаэратора д/быть в пределах 79-81%, температура 103-105С. Проверить на целостность приборов КИПиА. Убедиться в наличии регентов в баках, при необходимости, когда начнёт мигать красная лампочка на дозирующем устройстве бака, раствор наводится в бак в пропорции 1/9, одна часть химии, 9- воды умягченной воды. Заливать только с помощью контрольной канистры: гидрохим заливается по метке, остальное – вода после третьей ступени ХВО."},{"type":"text","text":"Убедиться в нормальной работе паровых котлов по информационному табло, проверить выставленные уставки по давлению, электропроводимости, работу газовой горелки. Проверить заполнение котлов водой через смотровые стёкла «УРОВЕНЬ ВОДЫ ДОЛЖЕН НАХОДИТЬСЯ НЕ НИЖЕ СТРЕЛКИ, ЗАКРЕПЛЁННОЙ НА КОРПУСЕ СМОТРОВОГО СТЕКЛА И НЕ ВЫШЕ 20 см. ОТ ВЕРХА   СМОТРОВОГО СТЕКЛА» Данные осмотра сравним с показаниями информационного табло шкафа управления котлами «40 и 70% соответственно». Заполнение котла поддерживается в объёме-60% в автоматическом режиме. Проверить на целостность взрывной клапан дымохода, положение заслонки на дымоходе. При открытом положении ручка заслонки находится вдоль дымохода. Проверить на плотность все фланцевые и другие соединения, сальниковые уплотнения запорной арматуры. Работа с системой управления и наблюдения осуществляется через сенсорный экран. Все необходимые объекты управления после запуска котла, появляются на сенсорном экране и в дальнейшем руководствуемся разделом инструкции «ПУСК И ОСТАНОВ КОТЛА»."},{"type":"text","text":"Проверить работу системы освещения рабочую и аварийную."},{"type":"text","text":"Переходя к осмотру системы отопления, убедиться в работе паровых теплообменников, циркуляционных насосов в системе отопления «перепад до насоса и после насоса должен быть не менее 1Атм». Информационное табло ТРМ должно показывать температуру в системе отопления в реальном времени и может отличаться от заданной не более чем на 1*С.  Значение температуры устанавливает энергетик по согласованию с гл. инженером или директором. Убедиться в правильности включения затворов на теплообменнике - все затворы д/быть открыты, работе запорно-регулирующего клапана, работе гидроаккумуляторов – шаровые краны Ду-25 д/быть открыты. Проверить на герметичность все фланцевые и другие соединения визуально. На «гребёнках» системы отопления на всех работающих отходящих трубопроводах затворы д/быть открыты. Вводные и выходные затворы на эл. котлах д/быть ЗАКРЫТЫ.  В случае работы системы отопления от эл. котлов, руководствоваться инструкцией «Работа эл. котлов в системе отопления»."},{"type":"text","text":"Убедиться в работе ГРУ по наличию давления на входе ГРУ—оно д/быть 6 атм, а на выходе из ГРУ к котлам 0,3атм. Все предохранительные клапаны взведены, шаровый кран перед ПСК (предохранительно-сбросной клапан) д/быть открыт. Проверить наличие давления перед газовой горелкой."},{"type":"text","text":"В течении смены поддерживать чистоту и порядок в котельной. Помещение котельной д/быть постоянно закрытым на замок, посторонних лиц в котельной быть НЕ ДОЛЖНО. Все действия при приёме смены и во время смены, обнаруженные недостатки записываем в «сменный журнал котельной»."},{"type":"text","text":"Прием – сдача смены записываются в «сменные журналы»."},{"type":"text","text":"Во время смены оператор каждые два часа делает обход котельной. В отсутствии оператора котельная должна быть закрыта, присутствие любых других людей в котельной кроме сотрудников службы энергетика категорически запрещено. Допускается присутствие посторонних лиц только в сопровождении оператора или сотрудников службы энергетика."},{"type":"text","text":"Перед каждой запаркой оператор проверяет наличие воды в баке ХВО на улице, полный уровень деаэратора. В зимнее время года очищает от снега территорию у ворот котельной и дорожки для подхода к бакам ХВО и конденсата на улице."},{"type":"text","text":"Следит за постоянным наличием хим. реагентов в котельной, при закачивании пополняет. Во время прихода соли открывает ворота в котельной и контролирует завозку соли. Следит за чистотой в котельной. Не должно быть никакого мусора, пустых поддонов и мешков из-под соли."}]};
